<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import ConversionReport, {type ConversionData} from '../../Components/ConversionReport.vue';
import HealthReport, {type HealthData} from '../../Components/HealthReport.vue';
import PopupFunnel, {type Funnel} from '../../Components/PopupFunnel.vue';
import OverviewReport, {type Report} from '../../Components/OverviewReport.vue';
import AppLayout from '../../../../../resources/js/Layouts/AppLayout.vue';

type Content={subject:string;body:string;button:string};
type Flow={uuid:string;key:string;name:string;enabled:boolean;version:number;steps:{template:string;after_minutes:number}[]};
type Template={is_customized:boolean;default_available:boolean;enabled:boolean;uuid:string;key:string;name:string;draft:Content;published:Content|null;version:number;tested_at:string|null};
type Settings={welcome_coupon?:string|null;coupons?:string[];warmup_enabled?:boolean;warmup_steps?:number[];enabled:boolean;daily_limit:number;frequency_hours:number;timezone:string;cutover_at:string;popup:{enabled:boolean;heading:string;body:string}};
type Row=Record<string,unknown>;
const props=defineProps<{
 organization:{id:number;name:string};store:{id:number;name:string;shopify_domain:string;currency:string};tab:string;
 conversion:ConversionData|null;overview:Report|null;campaignMetrics:Record<string,{audience:number;sent:number;opened:number;clicked:number;human_opened:number|null}>;templateMetrics:Record<string,number>;
 settings:Settings|null;transport:string;connected:boolean;canManage:boolean;stats:Record<string,number>;
 rows:{data:Row[];total:number;current_page:number;last_page:number;prev_page_url:string|null;next_page_url:string|null}|null;
 filters:{q:string;status:string;flow:string};flows:Flow[];templates:Template[];health:HealthData|null;popupStats:Funnel|null;
}>();
const base=`/organizations/${props.organization.id}/stores/${props.store.id}/marketing`;
const tabs=[['overview','总览'],['flows','流程'],['campaigns','群发'],['attribution','归因订单'],['templates','模板'],['contacts','联系人'],['waitlist','到货名单'],['popup','订阅弹窗'],['logs','发送日志'],['health','每日巡检']];
const title=computed(()=>tabs.find(t=>t[0]===props.tab)?.[1]??'总览');
function clone<T>(value:T):T { return JSON.parse(JSON.stringify(value)); }
const action=useForm({});
function change(name:string,data:Record<string,unknown>={}) { action.transform(()=>data).post(`${base}/actions/${name}`,{preserveScroll:true}); }
const setting=useForm<Settings>(props.settings?clone(props.settings):{enabled:false,daily_limit:100,frequency_hours:48,timezone:'America/Los_Angeles',cutover_at:'',popup:{enabled:false,heading:'Join our community',body:'Get product news and updates.'}});
const couponCodes=ref(props.settings?.coupons?.join(', ') || '');
const query=ref(props.filters.q),status=ref(props.filters.status);
const flowFilter=ref(props.filters.flow);
const flowChoices=[['welcome','欢迎系列'],['abandoned','弃购挽回'],['payment','待付款催付'],['back_in_stock','到货通知'],['cancelled','取消关怀'],['advocacy','骑行回访'],['campaign','群发'],['test','测试发送']];
function filter(){router.get(base,{tab:props.tab,q:query.value,status:status.value,flow:flowFilter.value},{preserveState:true,preserveScroll:true});}
const labels:Record<string,string>={subscribed:'已订阅',not_subscribed:'未订阅',pending:'待处理',unsubscribed:'已退订',suppressed:'禁止发送',sent:'已提交',delivered:'已投递',simulated:'预演完成',sending:'发送中',uncertain:'结果待确认',held:'需人工核对',failed:'失败',retry:'等待重试',skipped:'已跳过',active:'进行中',completed:'已完成',paused:'已暂停',draft:'草稿',cancelled:'已取消',waiting:'等待中',notified:'已通知',adjustment_required:'退款待核对',paid:'已付款',storefront:'店面订阅',import:'导入',shopify:'Shopify 同步',test:'测试'};
const reasons:Record<string,string>={smart_sending:'48小时内已收到营销邮件，本次跳过',template_disabled:'模板已停用',sender_snapshot_missing:'发件人记录缺失，需人工核对',recipient_not_allowed:'非授权测试邮箱',preview:'预演，没有发信',transport_not_configured:'发信通道未配置',provider_rejected:'服务商拒绝',provider_result_unknown:'服务商结果待确认',uncertain_requires_review:'结果待人工核对',payment_no_longer_pending:'订单已不需要催付',order_cancelled:'订单已取消',checkout_completed:'结账已完成',unsubscribed:'已退订',suppressed:'禁止发送',out_of_stock:'商品缺货',verification_unavailable:'无法核实 Shopify 最新状态',transport_mode_changed:'发信模式已变化',customer_purchased:'顾客已购买',unsubscribe_limit:'退订率超限'};
const audiences:Record<string,string>={subscribed:'全部订阅者',non_buyers:'订阅未购',buyers:'已购订阅者',advocacy_opened_not_clicked:'老带新已打开未点击'};
const label=(v:unknown)=>labels[String(v)]??String(v??'—');
const time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN',{timeZone:props.settings?.timezone??'UTC'}):'—';
const editor=ref<'flow'|'template'|'campaign'|null>(null);
const flowForm=useForm({uuid:'',enabled:false,steps:[] as Flow['steps']});
const editingName=ref('');
function editFlow(flow:Flow){editingName.value=flow.name;flowForm.uuid=flow.uuid;flowForm.enabled=flow.enabled;flowForm.steps=clone(flow.steps);editor.value='flow';}
const templateForm=useForm({uuid:'',content:{subject:'',body:'',button:'Visit store'}});
function editTemplate(t:Template){editingName.value=t.name;templateForm.uuid=t.uuid;templateForm.content=clone(t.draft);editor.value='template';}
const recipient=ref('jiushizheyike@gmail.com');
const templateRequest=ref(crypto.randomUUID());
function test(t:Template){change('template-test',{uuid:t.uuid,recipient:recipient.value,request_id:templateRequest.value});templateRequest.value=crypto.randomUUID();}
const campaignForm=useForm({smart_timing:false,name:'',audience:'subscribed',content:{subject:'',body:'',button:'Visit store'},variant_b:null as Content|null,test_percent:20});
const templateFlows=(t:Template)=>props.flows.filter(f=>f.steps.some(s=>s.template===t.key));
const templateState=(t:Template)=>!t.enabled?'已停用':!templateFlows(t).length?'未在序列中':templateFlows(t).some(f=>f.enabled)?`在发 · 30天 ${props.templateMetrics[t.key]??0} 封`:'流程未启用';
const draftPublished=(t:Template)=>JSON.stringify(t.draft)===JSON.stringify(t.published);
function campaignTest(row:Row,variant='A'){change('campaign-test',{uuid:row.uuid,recipient:recipient.value,request_id:crypto.randomUUID(),variant});}
const scheduled=ref('');
const importing=useForm({csv:'',digest:''});const importPreview=ref<{total:number;errors:string[];digest:string}|null>(null);const previewError=ref('');const previewing=ref(false);
async function preview(){previewing.value=true;previewError.value='';importPreview.value=null;try{const token=decodeURIComponent(document.cookie.split('; ').find(x=>x.startsWith('XSRF-TOKEN='))?.split('=').slice(1).join('=')??'');const response=await fetch(`${base}/import-preview`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-XSRF-TOKEN':token},body:JSON.stringify({csv:importing.csv})});const result=await response.json();if(!response.ok){previewError.value=result.message??'预检失败';return;}importPreview.value=result;importing.digest=result.digest;}catch{previewError.value='预检请求未成功，请重试。';}finally{previewing.value=false;}}
const wait=useForm({lines:''});
const selection=ref<{action:string;row:Row}|null>(null);
function confirmCampaign(){if(!selection.value)return;const d=selection.value;if(d.action==='template-reset'){change('template-reset',{uuid:d.row.uuid});selection.value=null;return;}change('campaign-transition',{uuid:d.row.uuid,action:d.action,scheduled_at:scheduled.value?new Date(scheduled.value).toISOString():null});selection.value=null;}
</script>

<template>
<Head title="营销自动化" />
<AppLayout :breadcrumbs="[{label:'应用中心'},{label:'营销自动化'}]">
 <div class="marketing">
  <header class="heading"><div><div class="eyebrow">DECO · MARKETING</div><h1>营销自动化</h1><p>{{store.name}} · 自动流程与邮件运营</p></div><span class="pilot">测试后台 · {{store.name}}</span></header>
  <div class="notice"><span class="dot"></span><div><strong>{{transport==='preview'?'预演模式 · 不发送真实邮件':'测试发信模式 · 仅限授权邮箱'}}</strong><p>{{connected?'独立 Shopify 应用已连接':'独立 Shopify 测试应用尚未连接'}}。旧 MACFOX CRM 保持运行。</p></div></div>
  <p v-for="error in action.errors" :key="String(error)" class="error" role="alert">{{error}}</p>
  <section v-if="!settings" class="panel empty"><h2>建立测试工作区</h2><p>创建联系人、模板和自动流程。所有流程默认关闭，不导入旧系统数据。</p><button v-if="canManage" class="primary" :disabled="action.processing" @click="change('initialize')">初始化测试工作区</button></section>
  <template v-else>
   <nav class="tabs" aria-label="营销功能"><Link v-for="tabItem in tabs" :key="tabItem[0]" :href="`${base}?tab=${tabItem[0]}`" :class="{selected:tab===tabItem[0]}" :aria-current="tab===tabItem[0]?'page':undefined">{{tabItem[1]}}</Link></nav>
   <div class="section-heading"><div><h2>{{title}}</h2><p v-if="tab==='overview'">先配置并启用流程，再在测试店铺验证完整链路。</p></div><div v-if="canManage" class="actions"><button :disabled="action.processing||!connected" @click="change('sync')">同步测试店铺</button><button class="primary" :disabled="action.processing||!settings.enabled" @click="change('run')">{{transport==='preview'?'运行一轮预演':'处理到期任务'}}</button></div></div>
   <template v-if="tab==='overview'">
    <ConversionReport v-if="conversion" :report="conversion"/><OverviewReport v-if="overview" :report="overview" :timezone="settings.timezone"/>
    <div class="two-cols"><section class="panel"><h3>自动流程</h3><div v-for="flow in flows" :key="flow.uuid" class="list-row"><div><strong>{{flow.name}}</strong><p>{{flow.steps.length}} 个步骤 · v{{flow.version}}</p></div><span class="badge" :class="{good:flow.enabled}">{{flow.enabled?'已启用':'已关闭'}}</span></div><Link class="text-link" :href="`${base}?tab=flows`">管理全部流程 →</Link></section>
    <form class="panel form" @submit.prevent="setting.post(`${base}/actions/settings`)"><h3>工作区设置</h3><label>欢迎邮件优惠码<input v-model="setting.welcome_coupon" maxlength="100" :disabled="!canManage"></label><p>实际发送前检查此代码在测试店中有效；未配置或失效时停止该邮件。</p><label>巡检优惠码（逗号分隔）<input v-model="couponCodes" :disabled="!canManage"></label><button v-if="canManage" type="button" @click="change('coupons',{codes:couponCodes.split(',').map(c=>c.trim()).filter(Boolean)})">保存巡检优惠码</button><label class="check"><input v-model="setting.enabled" type="checkbox" :disabled="!canManage">启用营销工作区</label><label class="check"><input v-model="setting.warmup_enabled" type="checkbox" :disabled="!canManage">启用域名预热自动升档</label><p>默认阶梯：第1周300、第2周800、第3周起5000；仅在健康线允许时升档。</p><label>每日发送上限<input v-model.number="setting.daily_limit" type="number" min="1" max="5000" :disabled="!canManage"></label><label>营销邮件间隔（小时）<input v-model.number="setting.frequency_hours" type="number" min="0" max="168" :disabled="!canManage"></label><label>统计时区<select v-model="setting.timezone" :disabled="!canManage"><option>America/Los_Angeles</option><option>America/New_York</option><option>Asia/Shanghai</option><option>UTC</option></select></label><p>流程时间从进入任务时计算。启用时间之前的历史事件不会自动补发。</p><p v-for="err in setting.errors" :key="err" class="error">{{err}}</p><button v-if="canManage" class="primary" :disabled="setting.processing">保存设置</button></form></div>
   </template>
   <template v-else-if="tab==='flows'"><div class="flow-grid"><article v-for="flow in flows" :key="flow.uuid" class="panel"><div class="section-heading"><h3>{{flow.name}}</h3><span class="badge" :class="{good:flow.enabled}">{{flow.enabled?'已启用':'已关闭'}}</span></div><ol class="steps"><li v-for="(step,i) in flow.steps" :key="i"><span>{{i+1}}</span><div><strong>{{step.template}}</strong><p>进入流程后 {{step.after_minutes<60?`${step.after_minutes} 分钟`:`${(step.after_minutes/60).toFixed(1)} 小时`}}</p></div></li></ol><button v-if="canManage" @click="editFlow(flow)">配置步骤与启停</button></article></div><div class="notice"><p>退订、禁止发送及对应订单状态在执行时重新核对。修改步骤只影响新任务，关闭流程会暂停现有任务的发送。</p></div></template>
   <template v-else-if="tab==='contacts'">
    <section v-if="canManage" class="panel form"><div class="section-heading"><h3>导入联系人</h3><a :href="`${base}/export-contacts`" class="text-link">导出联系人</a></div><p>每批最多 500 行。已订阅用户必须有同意时间；导入不会触发历史欢迎邮件，也不会覆盖已有退订状态。</p><textarea v-model="importing.csv" rows="5" placeholder="email,name,consent,consent_at&#10;test@example.com,Test,subscribed,2026-09-09T00:00:00Z" @input="importPreview=null;importing.digest=''"/><div class="actions"><button type="button" :disabled="previewing||!importing.csv" @click="preview">{{previewing?'正在预检…':'预检数据'}}</button><button class="primary" :disabled="!importPreview||importPreview.errors.length>0||importing.processing" @click="importing.post(`${base}/actions/import`)">确认导入</button></div><p v-if="importPreview">有效 {{importPreview.total}} 条；错误 {{importPreview.errors.length}} 条。</p><p v-for="err in importPreview?.errors" :key="err" class="error">{{err}}</p><p v-if="previewError" class="error">{{previewError}}</p><p v-for="err in importing.errors" :key="err" class="error">{{err}}</p></section>
   </template>
   <template v-else-if="tab==='templates'">
    <div class="panel"><label>测试收件邮箱<input v-model="recipient" type="email" :disabled="!canManage"></label><p>可自定义每套自动化流邮件的主题 / 正文 / 按钮文字；品牌头、退订链接和追踪固定保留。流程：保存草稿 → 发测试（必须）→ 发布生效。</p><p>投递状态看这封信在不在真发；当前生效和草稿状态说的是文案改没改，与发不发无关。</p></div>
    <section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>模板</th><th>投递状态</th><th>当前生效</th><th>草稿状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in templates" :key="t.uuid"><td><strong>{{t.name}}</strong><small>{{t.published?.subject??t.draft.subject}}</small></td><td><span class="badge" :class="{good:t.enabled&&templateFlows(t).some(f=>f.enabled)}">{{templateState(t)}}</span><small>{{templateFlows(t).map(f=>f.name).join('、')}}</small></td><td>{{!t.published?'尚未发布':t.is_customized?'已自定义':'代码默认'}}<small>v{{t.version}}</small></td><td>{{draftPublished(t)?'已发布·生效中':t.tested_at?'已测试·待发布':'未测试·待发布'}}</td><td><div v-if="canManage" class="actions"><button class="text-button" @click="editTemplate(t)">编辑</button><button class="text-button" :disabled="action.processing" @click="change('template-toggle',{uuid:t.uuid,enabled:!t.enabled})">{{t.enabled?'停用':'启用'}}</button><button class="text-button" :disabled="action.processing" @click="test(t)">发测试</button><button class="text-button" :disabled="!t.tested_at||draftPublished(t)||action.processing" @click="change('template-publish',{uuid:t.uuid})">{{draftPublished(t)?'已发布':'发布'}}</button><button class="text-button" :disabled="action.processing||!t.default_available" @click="selection={action:'template-reset',row:t}">恢复默认</button></div></td></tr></tbody></table></div></section>
   </template>
   <template v-else-if="tab==='campaigns'"><div class="notice"><p>群发只发给「已订阅且未压制」的联系人；发送前 48 小时内收到过营销邮件的人自动跳过（Smart Sending）。A/B 样本完成后观察 24 小时，按过滤后的打开率选优；没有可分类打开则等待，不自动放量。有打开且平局时使用 A。</p></div><button v-if="canManage" class="primary" @click="editor='campaign'">新建群发</button><label v-if="canManage">群发测试邮箱<input v-model="recipient" type="email"></label></template>
   <template v-else-if="tab==='waitlist'"><form v-if="canManage" class="panel form" @submit.prevent="wait.post(`${base}/actions/waitlist`)"><h3>导入到货名单</h3><p>每行：邮箱、SKU、商品名称（可选）。联系人必须已订阅且未被禁止发送；每批最多 200 行。</p><textarea v-model="wait.lines" rows="5" placeholder="email,sku,product title"/><p v-for="err in wait.errors" :key="err" class="error">{{err}}</p><button class="primary" :disabled="wait.processing">导入等待名单</button></form></template>
   <template v-else-if="tab==='popup'"><PopupFunnel v-if="popupStats" :report="popupStats" :base="base"/></template>
   <HealthReport v-else-if="tab==='health'&&health" :health="health" :daily-limit="settings.daily_limit" @refresh="router.reload()" />
   <template v-if="rows">
    <form v-if="['contacts','logs','waitlist'].includes(tab)" class="toolbar" @submit.prevent="filter"><input v-if="tab!=='waitlist'" v-model="query" placeholder="完整邮箱查询" aria-label="完整邮箱查询"><select v-if="tab==='logs'" v-model="flowFilter" aria-label="筛选流程"><option value="">全部流程</option><option v-for="f in flowChoices" :key="f[0]" :value="f[0]">{{f[1]}}</option></select><select v-model="status" aria-label="筛选状态"><option value="">全部状态</option><option v-for="s in tab==='contacts'?['subscribed','not_subscribed','unsubscribed','suppressed']:tab==='waitlist'?['waiting','notified']:['sent','delivered','simulated','failed','uncertain','held','skipped']" :key="s" :value="s">{{label(s)}}</option></select><button>筛选</button><span>共 {{rows.total}} 条</span></form>
    <section class="panel table-panel"><div class="table-scroll"><table><thead><tr><template v-if="tab==='contacts'"><th>联系人</th><th>来源</th><th>状态</th><th>订阅日期 / 入库日期</th><th>订单数</th><th>发送时区</th><th>操作</th></template><template v-else-if="tab==='logs'"><th>时间 / 流程</th><th>收件人 / 主题</th><th>状态</th><th>打开 / 点击</th><th>说明</th></template><template v-else-if="tab==='waitlist'"><th>邮箱</th><th>SKU / 商品</th><th>状态</th><th>通知时间</th></template><template v-else-if="tab==='campaigns'"><th>名称 / 主题</th><th>受众</th><th>状态</th><th>发送 / 真人打开 / 点击</th><th>操作</th></template><template v-else><th>订单</th><th>归因金额</th><th>客户</th><th>来源邮件</th><th>点击至下单</th><th>该客户未付订单</th></template></tr></thead><tbody>
     <tr v-for="row in rows.data" :key="String(row.uuid)"><template v-if="tab==='contacts'"><td>{{row.email}}<small>{{row.name}}</small></td><td>{{label(row.source)}}</td><td><span class="badge" :class="{good:row.consent==='subscribed'&&!row.suppressed}">{{row.suppressed?'禁止发送':label(row.consent)}}</span></td><td>{{time(row.consent_at||row.created_at)}}<small v-if="!row.consent_at">入库</small></td><td>{{row.orders_count}}</td><td><select :value="row.timezone||''" :disabled="!canManage" aria-label="联系人发送时区" @change="change('contact',{uuid:row.uuid,action:'timezone',timezone:($event.target as HTMLSelectElement).value})"><option disabled value="">跟随工作区</option><option>America/Los_Angeles</option><option>America/New_York</option><option>Asia/Shanghai</option><option>UTC</option><option v-if="row.timezone&&!(['America/Los_Angeles','America/New_York','Asia/Shanghai','UTC'].includes(String(row.timezone)))">{{row.timezone}}</option></select></td><td><div v-if="canManage" class="actions"><button class="text-button" @click="change('contact',{uuid:row.uuid,action:row.suppressed?'unsuppress':'suppress'})">{{row.suppressed?'解除禁止':'禁止发送'}}</button><button class="text-button" @click="change('contact',{uuid:row.uuid,action:'unsubscribe'})">退订</button></div></td></template>
     <template v-else-if="tab==='logs'"><td>{{time(row.created_at)}}<small>{{row.flow}} · 第 {{row.step}} 步</small></td><td>{{row.email}}<small>{{row.subject}}</small></td><td><span class="badge" :class="{good:['sent','delivered'].includes(String(row.status)),warn:['held','uncertain','failed'].includes(String(row.status))}">{{label(row.status)}}</span></td><td>{{row.opened_at?time(row.opened_at):'—'}}<small>点击 {{row.clicked_at?time(row.clicked_at):'—'}}</small><small>过滤后打开 {{row.human_opened_at?time(row.human_opened_at):'—'}}</small></td><td>{{reasons[String(row.reason)]??row.reason??'—'}}<small>尝试 {{row.attempts}} 次</small></td></template>
     <template v-else-if="tab==='waitlist'"><td>{{row.email}}</td><td>{{row.sku}}<small>{{row.product_title}}</small></td><td><span class="badge">{{label(row.status)}}</span></td><td>{{time(row.notified_at)}}</td></template>
     <template v-else-if="tab==='campaigns'"><td>{{row.name}}<small v-if="row.smart_timing">智能时段 09:00–12:00</small><small>{{(row.content as Content)?.subject}}</small><small>{{row.variant_b?'A/B 测试':'单版本'}} · {{row.winner?`优选 ${row.winner}`:''}}</small></td><td>{{audiences[String(row.audience)]??row.audience}}（{{campaignMetrics[String(row.id)]?.audience??0}}）</td><td><span class="badge">{{label(row.status)}}</span></td><td>{{campaignMetrics[String(row.id)]?.sent??0}} / {{campaignMetrics[String(row.id)]?.human_opened??'—'}} / {{campaignMetrics[String(row.id)]?.clicked??0}}</td><td><div v-if="canManage" class="actions"><button class="text-button" :disabled="action.processing" @click="campaignTest(row)">测试 A</button><button v-if="row.variant_b" class="text-button" :disabled="action.processing" @click="campaignTest(row,'B')">测试 B</button></div><div v-if="canManage&&!['completed','cancelled'].includes(String(row.status))" class="actions"><button v-if="row.status!=='sending'" class="text-button" @click="selection={action:'start',row}">{{row.status==='paused'?'恢复':'开始'}}</button><button v-else class="text-button" @click="selection={action:'pause',row}">暂停</button><button class="text-button danger" @click="selection={action:'cancel',row}">取消</button></div></td></template>
     <template v-else><td>{{row.order_name}}<small>{{time(row.ordered_at)}}</small><small>{{label(row.status)}}</small></td><td>{{row.revenue}} {{row.currency}}</td><td>{{row.email||'—'}}</td><td>{{row.flow}}<small>{{row.subject}}</small></td><td>{{row.click_minutes===null?'—':`${row.click_minutes} 分钟`}}</td><td><template v-if="(row.pending as {count:number;amount:string;currency:string}[])?.length"><div v-for="p in (row.pending as {count:number;amount:string;currency:string}[])" :key="p.currency">{{p.count}} 单 · {{p.amount??'待核对'}} {{p.currency}}</div><small>建议客服跟进</small></template><template v-else>—</template></td></template></tr>
     <tr v-if="!rows.data.length"><td colspan="5" class="empty">暂无记录。测试数据会保留在此工作区。</td></tr>
    </tbody></table></div><div class="pagination"><span>共 {{rows.total}} 条 · 第 {{rows.current_page}} / {{rows.last_page}} 页</span><div class="actions"><Link v-if="rows.prev_page_url" :href="rows.prev_page_url">上一页</Link><Link v-if="rows.next_page_url" :href="rows.next_page_url">下一页</Link></div></div></section>
   </template>
  </template>
  <div v-if="editor" class="modal" @click.self="editor=null"><section class="dialog"><div class="section-heading"><h2>{{editor==='campaign'?'创建群发草稿':editingName}}</h2><button class="text-button" aria-label="关闭编辑" @click="editor=null">关闭</button></div>
   <form v-if="editor==='flow'" class="form" @submit.prevent="flowForm.post(`${base}/actions/flow`,{onSuccess:()=>editor=null})"><label class="check"><input v-model="flowForm.enabled" type="checkbox">启用此流程</label><div v-for="(step,i) in flowForm.steps" :key="i" class="step-editor"><strong>第 {{i+1}} 步 · {{step.template}}</strong><label>进入流程后多少分钟<input v-model.number="step.after_minutes" type="number" min="0" max="525600" required></label></div><p v-for="err in flowForm.errors" :key="err" class="error">{{err}}</p><button class="primary" :disabled="flowForm.processing">保存流程</button></form>
   <form v-else-if="editor==='template'" class="form" @submit.prevent="templateForm.post(`${base}/actions/template`,{onSuccess:()=>editor=null})"><label>主题<input v-model="templateForm.content.subject" maxlength="200" required></label><label>正文<textarea v-model="templateForm.content.body" rows="9" maxlength="10000" required/></label><label>按钮文字<input v-model="templateForm.content.button" maxlength="80" required></label><p>可用变量：{firstName}、{storeName}、{orderName}、{productTitle}、{couponCode}、{referralCode}。链接由系统生成。</p><p v-for="err in templateForm.errors" :key="err" class="error">{{err}}</p><button class="primary" :disabled="templateForm.processing">保存草稿</button></form>
   <form v-else class="form" @submit.prevent="campaignForm.post(`${base}/actions/campaign`,{onSuccess:()=>{editor=null;campaignForm.reset()}})"><label>活动名称<input v-model="campaignForm.name" maxlength="150" required></label><label>受众<select v-model="campaignForm.audience"><option value="subscribed">全部订阅者</option><option value="non_buyers">未购订阅者</option><option value="buyers">已购订阅者</option><option value="advocacy_opened_not_clicked">老带新已打开未点击</option></select></label><label class="check"><input v-model="campaignForm.smart_timing" type="checkbox">智能时段：收件人当地 09:00–12:00</label><p>未设置联系人时区时使用工作区时区，不根据邮箱或IP猜测。</p><label>主题 A<input v-model="campaignForm.content.subject" maxlength="200" required></label><label>正文 A<textarea v-model="campaignForm.content.body" rows="5" required/></label><label>按钮文字<input v-model="campaignForm.content.button" required></label><button type="button" @click="campaignForm.variant_b=campaignForm.variant_b?null:clone(campaignForm.content)">{{campaignForm.variant_b?'移除 B 版本':'添加 A/B 测试'}}</button><template v-if="campaignForm.variant_b"><label>主题 B<input v-model="campaignForm.variant_b.subject" required maxlength="200"></label><label>正文 B<textarea v-model="campaignForm.variant_b.body" rows="5" required/></label><label>测试样本比例（%）<input v-model.number="campaignForm.test_percent" type="number" min="10" max="50"></label></template><p v-for="err in campaignForm.errors" :key="err" class="error">{{err}}</p><button class="primary" :disabled="campaignForm.processing">保存群发草稿</button></form>
  </section></div>
  <div v-if="selection" class="modal" @click.self="selection=null"><section class="dialog form"><h2>{{selection.action==='template-reset'?'恢复默认模板':selection.action==='start'?'开始或恢复群发':selection.action==='pause'?'暂停群发':'取消群发'}}</h2><p>{{selection.row.name}}</p><template v-if="selection.action==='start'"><p>仅处理当前店铺的数据；预演模式不会发送任何真实邮件。</p><label>定时开始（当前电脑时区，留空立即开始）<input v-model="scheduled" type="datetime-local"></label></template><p v-else-if="selection.action==='template-reset'">恢复默认将替换当前草稿和已发布版本，已有任务保留原邮件内容。</p><p v-else>已提交给邮件服务的邮件不能撤回。活动和发送记录会保留。</p><div class="actions"><button @click="selection=null">返回</button><button class="primary" :disabled="action.processing" @click="confirmCampaign">确认</button></div></section></div>
 </div>
</AppLayout>
</template>
